import React, { useState } from "react";
import {
  Box,
  Typography,
  Button,
  Card,
  CardContent,
  Chip,
  alpha,
} from "@mui/material";
import CheckIcon from "@mui/icons-material/Check";
import { useNavigate } from "react-router-dom";

// ─── PlanCard  ────────
export const PlanCard = ({ plan, index, selected, onSelect }) => {
  const isSelected = selected === index;
  const navigate = useNavigate();

  const handleButtonClick = (e) => {
    e.preventDefault();
    e.stopPropagation(); // Prevent card selection when clicking button

    // If custom plan (customPlan: true), go to contact page with planId
    if (plan.customPlan) {
      navigate(`/contact?planId=${plan._id}`);
    } else {
      // For shared plans, go to register page with planId
      navigate(`/register?planId=${plan._id}`);
    }
  };

  // Format price with currency symbol
  const formatPrice = (price) => {
    return `₹${price?.toLocaleString("en-IN") || "0"}`;
  };

  // Get the display price (monthly price) from billingOptions
  const displayPrice = formatPrice(plan.billingOptions?.monthly?.price);

  // Check if plan has any add-ons
  const hasAddOns = plan.addOns && plan.addOns.length > 0;

  return (
    <Box
      sx={{
        height: "100%",
        display: "flex",
        mt: { xs: "0px", sm: "0px", lg: plan.isPopular ? "0px" : "40px" },
      }}
    >
      <Card
        onClick={() => onSelect(isSelected ? null : index)}
        sx={{
          width: "100%",
          bgcolor: alpha("#FFFFFF", 0.95),
          borderRadius: { xs: "20px", md: "25px" },
          pt: plan.isPopular
            ? { xs: 5.5, sm: 6, md: 6.5 }
            : { xs: 3.5, sm: 4, md: 4.5 },
          px: { xs: 2.5, sm: 2.8, md: 3 },
          pb: { xs: 2.5, sm: 2.8, md: 3 },
          position: "relative",
          overflow: "visible",
          border: isSelected
            ? "3px solid #2e9e53"
            : plan.isPopular
              ? "3px solid #FFD23F"
              : "3px solid transparent",
          boxShadow: plan.isPopular
            ? "0 25px 60px rgba(0,0,0,0.35)"
            : isSelected
              ? "0 20px 50px rgba(0,0,0,0.3)"
              : "none",
          transform:
            isSelected && !plan.isPopular ? "translateY(-4px)" : "none",
          transition: "all 0.3s ease-in-out",
          cursor: "pointer",
          "&:hover": {
            transform: plan.isPopular ? "translateY(-4px)" : "translateY(-6px)",
            boxShadow: plan.isPopular
              ? "0 30px 70px rgba(0,0,0,0.4)"
              : "0 15px 40px rgba(0,0,0,0.2)",
          },
        }}
      >
        {plan.isPopular && (
          <Chip
            label="Most Popular"
            sx={{
              position: "absolute",
              top: "-16px",
              right: "20px",
              bgcolor: isSelected ? "#2e9e53" : "#FFD23F",
              color: isSelected ? "#FFFFFF" : "#1A1A2E",
              fontWeight: 700,
              fontSize: "0.82rem",
              textTransform: "uppercase",
              letterSpacing: "0.06em",
              height: "32px",
              borderRadius: "50px",
              zIndex: 10,
              transition: "all 0.3s ease-in-out",
              "& .MuiChip-label": { px: 2 },
            }}
          />
        )}

        <CardContent
          sx={{
            p: 0,
            height: "100%",
            display: "flex",
            flexDirection: "column",
          }}
        >
          {/* Plan Name */}
          <Typography
            sx={{
              fontFamily: "'Archivo Black', sans-serif",
              fontSize: { xs: "1.1rem", md: "1.3rem" },
              color: "#004E89",
              mb: 1,
              textTransform: "uppercase",
              letterSpacing: "0.05em",
            }}
          >
            {plan.name}
          </Typography>

          {/* Price */}
          <Box sx={{ mb: 0.5 }}>
            <Typography
              component="span"
              sx={{
                fontFamily: "'Archivo Black', sans-serif",
                fontSize: { xs: "2.5rem", md: "3.5rem" },
                color: "#1A1A2E",
                lineHeight: 1,
              }}
            >
              {displayPrice}
            </Typography>
            <Typography
              component="span"
              sx={{
                fontFamily: "'Archivo Black', sans-serif",
                fontSize: { xs: "1.2rem", md: "1.5rem" },
                color: "#2D3142",
                opacity: 0.6,
              }}
            >
              /month{" "}
            </Typography>
           
          </Box>

          {/* Title */}
          {plan.title && (
            <Typography
              sx={{
                fontFamily: "'DM Sans', sans-serif",
                fontWeight: 700,
                color: "#004E89",
                fontSize: "1rem",
                mb: 0.5,
              }}
            >
              {plan.title} { " "}
               <span
              style={{
                opacity: 0.6,
                fontSize: "14px",
                color: "#2D3142",
                fontFamily: " sans-serif",
              }}
            >
              +GST 
            </span>
            </Typography>
          )}

          {/* SubTitle */}
          {plan.subTitle && (
            <Typography
              sx={{
                fontFamily: "'DM Sans', sans-serif",
                color: "#2D3142",
                opacity: 0.8,
                mb: 2,
                fontSize: { xs: "0.9rem", md: "0.95rem" },
                fontStyle: "italic",
              }}
            >
              {plan.subTitle} 
              
            </Typography>
            
          )}

          {/* Setup Fee Note */}
          <Box
            sx={{
              bgcolor: plan.setupFee === 0 ? "#FFF9E6" : "#FFE8E0",
              p: { xs: 1.2, md: 1.5 },
              borderRadius: "8px",
              mb: 2,
              border: `1px solid ${plan.setupFee === 0 ? "#FFD23F" : "#FF6B35"}`,
            }}
          >
            <Typography
              sx={{
                color: "#1A1A2E",
                fontSize: { xs: "0.8rem", md: "0.85rem" },
                fontWeight: 600,
                textAlign: "center",
                textDecoration:
                  plan.setupFee === 0 || plan.customPlan
                    ? "none"
                    : "line-through",
              }}
            >
              {plan.setupFee === 0
                ? "No Setup Fee"
                : `Setup Fee: ${formatPrice(plan.setupFee)}`}
            </Typography>
            <span
              style={{
                display: "block", 
                textAlign: "center",
                opacity: 0.6,
                fontSize: "14px",
                color: "#2D3142",
                marginTop: "4px",
              }}
            >
             {plan.customPlan? "" : "Zero upfront cost"} 
            </span>
          </Box>

          {/* Features */}
          {plan.features && plan.features.length > 0 && (
            <Box sx={{ mb: hasAddOns ? 2 : 3, flex: 1 }}>
              {plan.features.map((feature, i) => (
                <Box
                  key={i}
                  sx={{
                    display: "flex",
                    alignItems: "flex-start",
                    gap: 1,
                    py: { xs: 0.8, md: 1 },
                    borderBottom: "1px solid rgba(0,0,0,0.05)",
                  }}
                >
                  <CheckIcon
                    sx={{
                      color: "#FF6B35",
                      fontSize: { xs: "1.1rem", md: "1.2rem" },
                      flexShrink: 0,
                      mt: 0.2,
                    }}
                  />
                  <Typography
                    sx={{
                      fontFamily: "'DM Sans', sans-serif",
                      fontSize: { xs: "0.85rem", md: "0.95rem" },
                      lineHeight: 1.5,
                    }}
                  >
                    {feature}
                  </Typography>
                </Box>
              ))}
            </Box>
          )}

          {/* Add-ons - Only show if they exist */}
          {hasAddOns && (
            <Box
              sx={{
                bgcolor: "#E8F4F8",
                p: { xs: 1.2, md: 1.5 },
                borderRadius: "8px",
                mb: 2,
                borderLeft: "3px solid #004E89",
              }}
            >
              <Typography
                sx={{
                  color: "#1A1A2E",
                  fontSize: { xs: "0.8rem", md: "0.85rem" },
                  fontWeight: 600,
                  mb: 1,
                }}
              >
                Available Add-ons:
              </Typography>
              {plan.addOns.map((addon, i) => (
                <Box key={i} sx={{ mb: i < plan.addOns.length - 1 ? 1 : 0 }}>
                  <Typography
                    sx={{
                      color: "#2D3142",
                      fontSize: { xs: "0.8rem", md: "0.85rem" },
                      fontWeight: 500,
                    }}
                  >
                    {addon.title} - {formatPrice(addon.price)}
                    {addon.billingType === "one-time"
                      ? " (one-time)"
                      : addon.billingType === "yearly"
                        ? " /year"
                        : " /month"}
                  </Typography>
                  {addon.description && (
                    <Typography
                      sx={{
                        color: "#2D3142",
                        fontSize: "0.75rem",
                        mt: 0.5,
                        opacity: 0.8,
                      }}
                    >
                      {addon.description}
                    </Typography>
                  )}
                </Box>
              ))}
            </Box>
          )}

          {/* Button */}
          <Button
            variant="contained"
            fullWidth
            onClick={handleButtonClick}
            sx={{
              mt: "auto",
              bgcolor: isSelected ? "#2e9e53" : "#0B4064",
              py: { xs: 1.3, md: 1.5 },
              fontSize: { xs: "1rem", md: "1.1rem" },
              fontWeight: 700,
              borderRadius: "50px",
              textTransform: "none",
              border: `2px solid ${isSelected ? "#2e9e53" : "#0B4064"}`,
              "&:hover": {
                bgcolor: isSelected ? "#0f5225" : "#1a1a3c",
                transform: "translateY(-2px)",
                boxShadow: "0 8px 20px rgba(0,0,0,0.3)",
              },
              transition: "all 0.3s",
            }}
          >
            {isSelected
              ? "Selected"
              : plan.customPlan
                ? "Contact Now"
                : "Start Your Journey "}
          </Button>
        </CardContent>
      </Card>
    </Box>
  );
};
