import React from 'react';
import { Box, Typography, Button, Zoom } from '@mui/material';
import { styled, keyframes } from "@mui/material/styles";
import { Link } from "react-router-dom"

const shimmer = keyframes`
  0% { background-position: -1000px 0; }
  100% { background-position: 1000px 0; }
`;
const GradientText = styled("span")(({ theme }) => ({
  background: "linear-gradient(135deg, #2E9E53 0%, #45B7A0 50%, #0B4064 100%)",
  WebkitBackgroundClip: "text",
  WebkitTextFillColor: "transparent",
  fontWeight: "inherit",
  backgroundSize: "200% 200%",
  animation: `${shimmer} 3s ease-in-out infinite`,
}));

const Hero = () => {
  const scrollToSection = (href) => {
    const element = document.querySelector(href);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <Box
      component="section"
      className="hero"
      sx={{
        marginTop: '80px',
        minHeight: '90vh',
        display: 'flex',
        alignItems: 'center',
        position: 'relative',
        overflow: 'hidden',
        background: 'linear-gradient(135deg, #F7F7F7 0%, #E8F4F8 100%)',
        '&::before': {
          content: '""',
          position: 'absolute',
          width: { xs: '300px', md: '600px' },
          height: { xs: '300px', md: '600px' },
          background: 'radial-gradient(circle, rgba(255, 107, 53, 0.1) 0%, transparent 70%)',
          top: '-100px',
          right: '-100px',
          borderRadius: '50%',
        },
      }}
    >
      <Box
        className="hero-content"
        sx={{
          width: '100%',
          maxWidth: '1400px',
          margin: '0 auto',
          padding: { xs: '2rem 1.25rem', sm: '3rem 2rem', lg: '4rem 2rem' },
          display: 'grid',
          gridTemplateColumns: { xs: '1fr', lg: '1.2fr 1fr' },
          gap: { xs: '2.5rem', md: '4rem' },
          alignItems: 'center',
          boxSizing: 'border-box',
        }}
      >
        {/* ── Text block ─────────────────────────────────────────────── */}
        <Box
          className="hero-text"
          sx={{
            textAlign: { xs: 'center', lg: 'left' },
          }}
        >
          <Zoom in timeout={1000}>
          <Typography
            component="h1"
            sx={{
              fontFamily: "'Archivo Black', sans-serif",
              fontSize: { xs: '2rem', sm: '2.8rem', md: '3.5rem', lg: '4.5rem' },
              lineHeight: 1.15,
              marginBottom: { xs: '1rem', md: '1.5rem' },
              color: '#1A1A2E',
              wordBreak: 'break-word',
              animation: 'slideUp 0.8s ease-out',
              '@keyframes slideUp': {
                from: { opacity: 0, transform: 'translateY(30px)' },
                to: { opacity: 1, transform: 'translateY(0)' },
              },
            }}
          >
            Give Your Dealers a{' '}
            {/* <Box
              component="span"
              sx={{
                color: '#2e9e53',
                position: 'relative',
                display: 'inline-block',
                fontWeight:800
              }}
            >
              Mobile App
            </Box>{' '} */}
              
                        <Box
                         component="span"
                          variant="h2"
                          sx={{
                            fontWeight: 800,
                            color: "#0B4064",
                             position: 'relative',
                display: 'inline-block',

                          }}
                        >
                       <GradientText> Mobile App</GradientText> to
                        </Box>
            Order 24/7
          </Typography>
                      </Zoom>

          <Typography
            component="p"
            sx={{
              fontSize: { xs: '1rem', sm: '1.1rem', md: '1.3rem' },
              fontFamily: "'DM Sans', sans-serif",
              lineHeight: 1.6,
              marginBottom: { xs: '1.5rem', md: '2rem' },
              color: '#2D3142',
              opacity: 0.9,
              animation: 'slideUp 0.8s ease-out 0.2s both',
              // Prevent text overflow on xs
              wordBreak: 'break-word',
              overflowWrap: 'break-word',
            }}
          >
            Stop the WhatsApp chaos. Get instant orders, faster payments, and complete visibility into your dealer network—24/7.
          </Typography>

          {/* ── CTA Buttons ─────────────────────────────────────── */}
          <Box
            className="hero-buttons"
            sx={{
              display: 'flex',
              flexDirection: { xs: 'column', sm: 'row' },
              gap: { xs: '0.875rem', sm: '1rem', md: '1.5rem' },
              justifyContent: { xs: 'center', lg: 'flex-start' },
              animation: 'slideUp 0.8s ease-out 0.4s both',
            }}
          >
            <Button
              href="#pricing"
              onClick={(e) => {
                e.preventDefault();
                scrollToSection('#pricing');
              }}
              sx={{
                background: '#2e9e53',
                color: 'white',
                padding: { xs: '0.9rem 2rem', md: '1.2rem 2.5rem' },
                borderRadius: '50px',
                fontWeight: 700,
                fontSize: { xs: '1rem', md: '1.1rem' },
                transition: 'all 0.3s',
                border: '2px solid #2e9e53',
                textTransform: 'none',
                width: { xs: '100%', sm: 'auto' },
                '&:hover': {
                  background: '#2e9e53',
                  transform: 'translateY(-3px)',
                  boxShadow: '0 10px 30px rgba(30, 163, 34, 0.3)',
                },
              }}
            >
              {/* Start Free Trial */}
              Start Your Journey 
            </Button>
            <Button
              component={Link}
                  to="/contact"
              sx={{
                background: 'white',
                color: '#2e9e53',
                padding: { xs: '0.9rem 2rem', md: '1.2rem 2.5rem' },
                borderRadius: '50px',
                fontWeight: 700,
                fontSize: { xs: '1rem', md: '1.1rem' },
                transition: 'all 0.3s',
                border: '2px solid #2e9e53',
                textTransform: 'none',
                width: { xs: '100%', sm: 'auto' },
                '&:hover': {
                  background: '#0B4064',
                  border: '2px solid #0B4064',
                  color: 'white',
                },
              }}
            >
              Schedule Demo
            </Button>
          </Box>

          {/* ── Stats ───────────────────────────────────────────── */}
          <Box
            className="hero-stats"
            sx={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: { xs: '1.5rem', sm: '2rem', md: '3rem' },
              marginTop: { xs: '2rem', md: '3rem' },
              justifyContent: { xs: 'center', lg: 'flex-start' },
              animation: 'slideUp 0.8s ease-out 0.6s both',
            }}
          >
            {[
              { number: '15 Days', label: 'Faster Payments' },
              { number: '₹0', label: 'Setup Fee' },
              { number: '5min', label: 'To Start' },
            ].map((stat, index) => (
              <Box key={index} sx={{ textAlign: 'center', minWidth: '70px' }}>
                <Typography
                  component="span"
                  sx={{
                    fontFamily: "'Archivo Black', sans-serif",
                    fontSize: { xs: '1.8rem', sm: '2rem', md: '2.5rem' },
                    color: '#0B4064',
                    display: 'block',
                  }}
                >
                  {stat.number}
                </Typography>
                <Typography
                  component="span"
                  sx={{
                    fontSize: { xs: '0.75rem', md: '0.9rem' },
                    color: '#2D3142',
                    opacity: 0.7,
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                  }}
                >
                  {stat.label}
                </Typography>
              </Box>
            ))}
          </Box>
        </Box>

        {/* ── Phone Visual ────────────────────────────────────────────── */}
        <Box
          className="hero-visual"
          sx={{
            position: 'relative',
            animation: 'fadeIn 1s ease-out 0.4s both',
            display: 'flex',
            justifyContent: 'center',
            '@keyframes fadeIn': {
              from: { opacity: 0 },
              to: { opacity: 1 },
            },
          }}
        >
          <Box
            className="phone-mockup"
            sx={{
              width: '100%',
              maxWidth: { xs: '240px', sm: '300px', md: '360px', lg: '400px' },
              margin: '0 auto',
              position: 'relative',
              zIndex: 2,
            }}
          >
            <Box
              className="phone-frame"
              sx={{
                background: '#1A1A2E',
                borderRadius: '40px',
                padding: '15px',
                boxShadow: '0 30px 60px rgba(0, 0, 0, 0.3)',
                transform: 'rotate(-5deg)',
                transition: 'transform 0.5s',
                '&:hover': {
                  transform: 'rotate(0deg) scale(1.05)',
                },
              }}
            >
              <Box
                className="phone-screen"
                sx={{
                  background: 'white',
                  borderRadius: '30px',
                  overflow: 'hidden',
                  aspectRatio: '9/19.5',
                }}
              >
                <Box
                  className="app-preview"
                  sx={{
                    background: 'linear-gradient(180deg, #0B4064 0%, #2e9e53 100%)',
                    padding: { xs: '1.5rem 1rem', md: '2rem 1.5rem' },
                    color: 'white',
                    height: '100%',
                  }}
                >
                  <Box sx={{ marginBottom: '1.5rem' }}>
                    <Typography
                      sx={{
                        fontFamily: "'Archivo Black', sans-serif",
                        fontSize: { xs: '1rem', md: '1.2rem' },
                        marginBottom: '0.5rem',
                      }}
                    >
                      BIZBRIDGE
                    </Typography>
                    <Typography sx={{ fontSize: '0.75rem', opacity: 0.9 }}>
                      Dealer Portal
                    </Typography>
                  </Box>
                  {[
                    { label: 'Outstanding', value: '₹3,45,000' },
                    { label: 'Orders This Month', value: '24 Orders' },
                    { label: 'Credit Available', value: '₹2,00,000' },
                  ].map((item, index) => (
                    <Box
                      key={index}
                      sx={{
                        background: 'rgba(255, 255, 255, 0.95)',
                        borderRadius: '15px',
                        padding: { xs: '0.75rem', md: '1rem' },
                        marginBottom: '0.8rem',
                        color: '#2D3142',
                        boxShadow: '0 4px 15px rgba(0, 0, 0, 0.1)',
                      }}
                    >
                      <Typography
                        sx={{
                          fontSize: '0.65rem',
                          color: '#0B4064',
                          textTransform: 'uppercase',
                          fontWeight: 700,
                          letterSpacing: '0.05em',
                          marginBottom: '0.3rem',
                        }}
                      >
                        {item.label}
                      </Typography>
                      <Typography
                        sx={{
                          fontSize: { xs: '0.9rem', md: '1.1rem' },
                          fontWeight: 700,
                          color: '#1A1A2E',
                        }}
                      >
                        {item.value}
                      </Typography>
                    </Box>
                  ))}
                </Box>
              </Box>
            </Box>
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

export default Hero;