import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "../../axiosInstance";

const safeProfileCompletion = (payloadProfileCompletion) => ({
  ...initialState.profileCompletion,
  ...(payloadProfileCompletion || {}),
});


const initialState = {
  user: null,
  token: null,
  isAuthenticated: false,
  loading: false,
  error: null,
  adminAllUsers: [],
  profileCompletion: {
    percentage: 0,
    missingFields: [],
    sectionCompletion: {},
    isProfileComplete: false,
    nextSteps: [],
  },
  operations: {
    profileUpdate: { loading: false, success: false, error: null },
    passwordUpdate: { loading: false, success: false, error: null },
    forgotPassword: {
      loading: false,
      success: false,
      error: null,
      message: null,
    },
    otpVerification: {
      loading: false,
      success: false,
      error: null,
      token: null,
    },
    imageUpload: { loading: false, success: false, error: null },
    imageDelete: { loading: false, success: false, error: null },
  },
};

// Async Thunks
export const userRegister = createAsyncThunk(
  "user/register",
  async (userData, { rejectWithValue }) => {
    try {
      const { data } = await axios.post("/api/v1/auth/register", userData);
      if (!data.token) {
        return rejectWithValue("No token returned from server");
      }

      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user));
      localStorage.setItem("refreshToken", data.refreshToken);

      return {
        user: data.user,
        token: data.token,
        profileCompletion: data.profileCompletion || initialState.profileCompletion
      };
    } catch (err) {
      const message =
        err.response?.data?.message || err.message || "Registration failed";
      return rejectWithValue(message);
    }
  }
);

